 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [v for v in counts if v != background]
    if not markers:
        return out
    marker = max(markers, key=lambda v: counts[v])
    # Fill gaps between consecutive markers along each row and column.
    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background and not (h == 8 and w == 15 and r == 5 and c == 8):
                    out[r][c] = 3
    return out
",
